    r0,c0=min(rs),min(cs)
    return frozenset((r-r0,c-c0) for r,c in cells)

def transform(g):
    H,W=len(g),len(g[0])
    wall=g[0][0]
    # box width: columns until a column that is all zeros
    bw=0
    for c in range(W):
        if any(g[r][c]!=0 for r in range(H)): bw=c+1
    # shapes: connected components of nonzero non-wall right of box
    seen=set(); shapes=[]
    for r in range(H):
        for c in range(bw,W):
            if g[r][c] and (r,c) not in seen:
                col=g[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
                while stack:
                    a,b=stack.pop(); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and bw<=y<W and g[x][y]==col and (x,y) not in seen:
                            seen.add((x,y)); stack.append((x,y))
                shapes.append((col,norm(cells)))
    # holes: 0-regions within box
    seen=set(); holes=[]
    for r in range(H):
        for c in range(bw):
            if g[r][c]==0 and (r,c) not in seen:
                stack=[(r,c)]; seen.add((r,c)); cells=[]
